    Ayah(1, 96, "اِقْرَأْ بِاسْمِ رَبِّكَ الَّذِيْ خَلَقَۚ", "Iqra' bismi rabbikal-lażī khalaq(a).", "Bacalah dengan (menyebut) nama Tuhanmu yang menciptakan!"),
    Ayah(2, 96, "خَلَقَ الْاِنْسَانَ مِنْ عَلَقٍۚ", "Khalaqal-insāna min ‘alaq(in).", "Dia menciptakan manusia dari segumpal darah."),
    Ayah(3, 96, "اِقْرَأْ وَرَبُّكَ الْاَكْرَمُۙ", "Iqra' wa rabbukal-akram(u).", "Bacalah! Tuhanmulah Yang Mahamulia,"),
    Ayah(4, 96, "الَّذِيْ عَلَّمَ بِالْقَلَمِۙ", "Allażī ‘allama bil-qalam(i).", "yang mengajar (manusia) dengan pena."),
    Ayah(5, 96, "عَلَّمَ الْاِنْسَانَ مَا لَمْ يَعْلَمْۗ", "‘Allamal-insāna mā lam ya‘lam.", "Dia mengajarkan manusia apa yang tidak diketahuinya."),
