    Ayah(7, 96, "اَنْ رَّاٰهُ اسْتَغْنٰىۗ", "Ar ra'āhustagnā.", "ketika melihat dirinya serba berkecukupan."),
    Ayah(8, 96, "اِنَّ اِلٰى رَبِّكَ الرُّجْعٰىۗ", "Inna ilā rabbikar-ruj‘ā.", "Sesungguhnya hanya kepada Tuhanmulah tempat kembali(-mu)."),
    Ayah(9, 96, "اَرَاَيْتَ الَّذِيْ يَنْهٰىۙ", "Ara'aital-lażī yanhā.", "Tahukah kamu tentang orang yang melarang"),
    Ayah(10, 96, "عَبْدًا اِذَا صَلّٰىۗ", "‘Abdan iżā ṣallā.", "seorang hamba ketika dia melaksanakan salat?"),
    Ayah(11, 96, "اَرَاَيْتَ اِنْ كَانَ عَلَى الْهُدٰىٓۙ", "Ara'aita in kāna ‘alal-hudā.", "Bagaimana pendapatmu kalau terbukti dia berada di dalam kebenaran"),
    Ayah(12, 96, "اَوْ اَمَرَ بِالتَّقْوٰىۗ", "Au amara bit-taqwā.", "atau dia menyuruh bertakwa (kepada اللّه)?"),
    Ayah(13, 96, "اَرَاَيْتَ اِنْ كَذَّبَ وَتَوَلّٰىۗ", "Ara'aita in każżaba wa tawallā.", "Bagaimana pendapatmu kalau dia mendustakan (kebenaran) dan berpaling (dari keimanan)?"),
    Ayah(14, 96, "اَلَمْ يَعْلَمْ بِاَنَّ اللّٰهَ يَرٰىۗ", "Alam ya‘lam bi'annallāha yarā.", "Tidakkah dia mengetahui bahwa sesungguhnya اللّه melihat (segala perbuatannya)?"),
    Ayah(15, 96, "كَلَّا لَىِٕنْ لَّمْ يَنْتَهِ ەۙ لَنَسْفَعًاۢ بِالنَّاصِيَةِۙ", "Kallā la'il lam yantah(i), lanasfa‘am bin-nāṣiyah(ti).", "Sekali-kali tidak! Sungguh, jika dia tidak berhenti (berbuat demikian), niscaya Kami tarik ubun-ubunnya (ke dalam neraka),"),
    Ayah(16, 96, "نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍۚ", "Nāṣiyatin kāżibatin khāṭi'ah(tin).", "(yaitu) ubun-ubun orang yang mendustakan (kebenaran) dan durhaka."),
    Ayah(17, 96, "فَلْيَدْعُ نَادِيَهٗۙ", "Falyad‘u nādiyah(ū).", "Biarlah dia memanggil golongannya (untuk menolongnya)."),
    Ayah(18, 96, "سَنَدْعُ الزَّبَانِيَةَۙ", "Sanad‘uz-zabāniyah(ta).", "Kelak Kami akan memanggil (Malaikat) Zabaniah (penyiksa orang-orang yang berdosa)."),
    Ayah(19, 96, "كَلَّاۗ لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ ۩ ࣖ", "Kallā, lā tuṭi‘hu wasjud waqtarib.", "Sekali-kali tidak! Janganlah patuh kepadanya, (tetapi) sujud dan mendekatlah (kepada اللّه)."),
)

internal fun quranFullAyahs97(): List<Ayah> = listOf(
    Ayah(1, 97, "اِنَّآ اَنْزَلْنٰهُ فِيْ لَيْلَةِ الْقَدْرِ", "Innā anzalnāhu fī lailatil-qadr(i).", "Sesungguhnya Kami telah menurunkannya (Al-Qur’an) pada Lailatulqadar."),
    Ayah(2, 97, "وَمَآ اَدْرٰىكَ مَا لَيْلَةُ الْقَدْرِۗ", "Wa mā adrāka mā lailatul-qadr(i).", "Tahukah kamu apakah Lailatulqadar itu?"),
    Ayah(3, 97, "لَيْلَةُ الْقَدْرِ ەۙ خَيْرٌ مِّنْ اَلْفِ شَهْرٍۗ", "Lailatul-qadri khairum min alfi syahr(in).", "Lailatulqadar itu lebih baik daripada seribu bulan."),
    Ayah(4, 97, "تَنَزَّلُ الْمَلٰۤىِٕكَةُ وَالرُّوْحُ فِيْهَا بِاِذْنِ رَبِّهِمْۚ مِنْ كُلِّ اَمْرٍۛ", "Tanazzalul-malā'ikatu war rūḥu fīhā bi'iżni rabbihim min kulli amr(in).", "Pada malam itu turun para malaikat dan Rūḥ (Jibril) dengan izin Tuhannya untuk mengatur semua urusan."),
    Ayah(5, 97, "سَلٰمٌ ۛهِيَ حَتّٰى مَطْلَعِ الْفَجْرِ ࣖ", "Salāmun hiya ḥattā maṭla‘il-fajr(i).", "Sejahteralah (malam) itu sampai terbit fajar."),
)

internal fun quranFullAyahs98(): List<Ayah> = listOf(
    Ayah(1, 98, "لَمْ يَكُنِ الَّذِيْنَ كَفَرُوْا مِنْ اَهْلِ الْكِتٰبِ وَالْمُشْرِكِيْنَ مُنْفَكِّيْنَ حَتّٰى تَأْتِيَهُمُ الْبَيِّنَةُۙ", "Lam yakunil-lażīna kafarū min ahlil-kitābi wal-musyrikīna munfakkīna ḥattā ta'tiyahumul-bayyinah(tu).", "Orang-orang yang kufur dari golongan Ahlulkitab dan orang-orang musyrik tidak akan meninggalkan (kekufuran mereka) sampai datang kepada mereka bukti yang nyata,"),
    Ayah(2, 98, "رَسُوْلٌ مِّنَ اللّٰهِ يَتْلُوْا صُحُفًا مُّطَهَّرَةًۙ", "Rasūlum minallāhi yatlū ṣuḥufam muṭahharah(tan).", "(yaitu) seorang Rasul dari اللّه (Nabi Muhammad) yang membacakan lembaran-lembaran suci (Al-Qur’an)"),
    Ayah(3, 98, "فِيْهَا كُتُبٌ قَيِّمَةٌ ۗ", "Fīhā kutubun qayyimah(tun).", "yang di dalamnya terdapat (isi) kitab-kitab yang lurus (benar)."),
    Ayah(4, 98, "وَمَا تَفَرَّقَ الَّذِيْنَ اُوْتُوا الْكِتٰبَ اِلَّا مِنْۢ بَعْدِ مَا جَاۤءَتْهُمُ الْبَيِّنَةُ ۗ", "Wa mā tafarraqal-lażīna ūtul-kitāba illā mim ba‘di mā jā'athumul-bayyinah(tu).", "Tidaklah terpecah-belah orang-orang Ahlulkitab, melainkan setelah datang kepada mereka bukti yang nyata."),
    Ayah(5, 98, "وَمَآ اُمِرُوْٓا اِلَّا لِيَعْبُدُوا اللّٰهَ مُخْلِصِيْنَ لَهُ الدِّيْنَ ەۙ حُنَفَاۤءَ وَيُقِيْمُوا الصَّلٰوةَ وَيُؤْتُوا الزَّكٰوةَ وَذٰلِكَ دِيْنُ الْقَيِّمَةِۗ", "Wa mā umirū illā liya‘budullāha mukhliṣīna lahud-dīn(a), ḥunafā'a wa yuqīmuṣ-ṣalāta wa yu'tuz-zakāta wa żālika dīnul-qayyimah(ti).", "Mereka tidak diperintah, kecuali untuk menyembah اللّه dengan mengikhlaskan ketaatan kepada-Nya lagi hanif (istikamah), melaksanakan salat, dan menunaikan zakat. Itulah agama yang lurus (benar)."),
    Ayah(6, 98, "اِنَّ الَّذِيْنَ كَفَرُوْا مِنْ اَهْلِ الْكِتٰبِ وَالْمُشْرِكِيْنَ فِيْ نَارِ جَهَنَّمَ خٰلِدِيْنَ فِيْهَاۗ اُولٰۤىِٕكَ هُمْ شَرُّ الْبَرِيَّةِۗ", "Innal-lażīna kafarū min ahlil-kitābi wal-musyrikīna fī nāri jahannama khālidīna fīhā, ulā'ika hum syarrul-bariyyah(ti).", "Sesungguhnya orang-orang yang kufur dari golongan Ahlulkitab dan orang-orang musyrik (akan masuk) neraka Jahanam. Mereka kekal di dalamnya. Mereka itulah seburuk-buruk makhluk."),
    Ayah(7, 98, "اِنَّ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ اُولٰۤىِٕكَ هُمْ خَيْرُ الْبَرِيَّةِۗ", "Innal-lażīna āmanū wa ‘amiluṣ-ṣāliḥāti ulā'ika hum khairul-bariyyah(ti).", "Sesungguhnya orang-orang yang beriman dan mengerjakan kebajikan, mereka itulah sebaik-baik makhluk."),
    Ayah(8, 98, "جَزَاۤؤُهُمْ عِنْدَ رَبِّهِمْ جَنّٰتُ عَدْنٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَآ اَبَدًا ۗرَضِيَ اللّٰهُ عَنْهُمْ وَرَضُوْا عَنْهُ ۗ ذٰلِكَ لِمَنْ خَشِيَ رَبَّهٗ ࣖ", "Jazā'uhum ‘inda rabbihim jannātu ‘adnin tajrī min taḥtihal-anhāru khālidīna fīhā abadā(n), raḍiyallāhu ‘anhum wa raḍū ‘anh(u), żālika liman khasyiya rabbah(ū).", "Balasan mereka di sisi Tuhannya adalah surga ‘Adn yang mengalir di bawahnya sungai-sungai. Mereka kekal di dalamnya selama-lamanya. اللّه rida terhadap mereka dan mereka pun rida kepada-Nya. Itu adalah (balasan) bagi orang yang takut kepada Tuhannya."),
)

internal fun quranFullAyahs99(): List<Ayah> = listOf(
    Ayah(1, 99, "اِذَا زُلْزِلَتِ الْاَرْضُ زِلْزَالَهَاۙ", "Iżā zulzilatil-arḍu zilzālahā.", "Apabila bumi diguncangkan dengan guncangan yang dahsyat,"),
    Ayah(2, 99, "وَاَخْرَجَتِ الْاَرْضُ اَثْقَالَهَاۙ", "Wa akhrajatil-arḍu aṡqālahā.", "bumi mengeluarkan isi perutnya,"),
    Ayah(3, 99, "وَقَالَ الْاِنْسَانُ مَا لَهَاۚ", "Wa qālal-insānu mā lahā.", "dan manusia bertanya, “Apa yang terjadi dengannya (bumi)?”"),
    Ayah(4, 99, "يَوْمَىِٕذٍ تُحَدِّثُ اَخْبَارَهَاۙ", "Yauma'iżin tuḥaddiṡu akhbārahā.", "Pada hari itu (bumi) menyampaikan berita (tentang apa yang diperbuat manusia di atasnya)"),
    Ayah(5, 99, "بِاَنَّ رَبَّكَ اَوْحٰى لَهَاۗ", "Bi'anna rabbaka auḥā lahā.", "karena sesungguhnya Tuhanmu telah memerintahkan (yang demikian itu) kepadanya."),
    Ayah(6, 99, "يَوْمَىِٕذٍ يَّصْدُرُ النَّاسُ اَشْتَاتًا ەۙ لِّيُرَوْا اَعْمَالَهُمْۗ", "Yauma'iżiy yaṣdurun-nāsu asytātā(n), liyurau a‘mālahum.", "Pada hari itu manusia keluar (dari kuburnya) dalam keadaan terpencar untuk diperlihatkan kepada mereka (balasan) semua perbuatan mereka."),
    Ayah(7, 99, "فَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَّرَهٗۚ", "Famay ya‘mal miṡqāla żarratin khairay yarah(ū).", "Siapa yang mengerjakan kebaikan seberat zarah, dia akan melihat (balasan)-nya."),
    Ayah(8, 99, "وَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَّرَهٗ ࣖ", "Wa may ya‘mal miṡqāla żarratin syarray yarah(ū).", "Siapa yang mengerjakan kejahatan seberat zarah, dia akan melihat (balasan)-nya."),
)

internal fun quranFullAyahs100(): List<Ayah> = listOf(
    Ayah(1, 100, "وَالْعٰدِيٰتِ ضَبْحًاۙ", "Wal-‘ādiyāti ḍabḥā(n).", "Demi kuda-kuda perang yang berlari kencang terengah-engah,"),
    Ayah(2, 100, "فَالْمُوْرِيٰتِ قَدْحًاۙ", "Fal-mūriyāti qadḥā(n).", "yang memercikkan bunga api (dengan entakan kakinya),"),
    Ayah(3, 100, "فَالْمُغِيْرٰتِ صُبْحًاۙ", "Fal-mugīrāti ṣubḥā(n).", "yang menyerang (dengan tiba-tiba) pada waktu pagi"),
    Ayah(4, 100, "فَاَثَرْنَ بِهٖ نَقْعًاۙ", "Fa'aṡarna bihī naq‘ā(n).", "sehingga menerbangkan debu,"),
    Ayah(5, 100, "فَوَسَطْنَ بِهٖ جَمْعًاۙ", "Fawasaṭna bihī jam‘ā(n).", "lalu menyerbu ke tengah-tengah kumpulan musuh,"),
    Ayah(6, 100, "اِنَّ الْاِنْسَانَ لِرَبِّهٖ لَكَنُوْدٌ ۚ", "Innal-insāna lirabbihī lakanūd(un).", "sesungguhnya manusia itu sangatlah ingkar kepada Tuhannya."),
    Ayah(7, 100, "وَاِنَّهٗ عَلٰى ذٰلِكَ لَشَهِيْدٌۚ", "Wa innahū ‘alā żālika lasyahīd(un).", "Sesungguhnya dia benar-benar menjadi saksi atas hal itu (keingkarannya)."),
    Ayah(8, 100, "وَاِنَّهٗ لِحُبِّ الْخَيْرِ لَشَدِيْدٌ ۗ", "Wa innahū liḥubbil-khairi lasyadīd(un).", "Sesungguhnya cintanya pada harta benar-benar berlebihan."),
    Ayah(9, 100, "۞ اَفَلَا يَعْلَمُ اِذَا بُعْثِرَ مَا فِى الْقُبُوْرِۙ", "Afalā ya‘lamu iżā bu‘ṡira mā fil-qubūr(i).", "Maka, tidakkah dia mengetahui (apa yang akan dialaminya) apabila dikeluarkan apa yang ada di dalam kubur"),
    Ayah(10, 100, "وَحُصِّلَ مَا فِى الصُّدُوْرِۙ", "Wa ḥuṣṣila mā fiṣ-ṣudūr(i).", "dan ditampakkan apa yang tersimpan di dalam dada?"),
    Ayah(11, 100, "اِنَّ رَبَّهُمْ بِهِمْ يَوْمَىِٕذٍ لَّخَبِيْرٌ ࣖ", "Inna rabbahum bihim yauma'iżil lakhabīr(un).", "Sesungguhnya Tuhan mereka pada hari itu benar-benar Mahateliti terhadap (keadaan) mereka."),
)

internal fun quranFullAyahs101(): List<Ayah> = listOf(
    Ayah(1, 101, "اَلْقَارِعَةُۙ", "Al-qāri‘ah(tu).", "Al-Qāri‘ah (hari Kiamat yang menggetarkan)."),
    Ayah(2, 101, "مَا الْقَارِعَةُ ۚ", "Mal-qāri‘ah(tu).", "Apakah al-Qāri‘ah itu?"),
    Ayah(3, 101, "وَمَآ اَدْرٰىكَ مَا الْقَارِعَةُ ۗ", "Wa mā adrāka mal-qāri‘ah(tu).", "Tahukah kamu apakah al-Qāri‘ah itu?"),
    Ayah(4, 101, "يَوْمَ يَكُوْنُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوْثِۙ", "Yauma yakūnun-nāsu kal-farāsyil-mabṡūṡ(i).", "Pada hari itu manusia seperti laron yang beterbangan"),
    Ayah(5, 101, "وَتَكُوْنُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوْشِۗ", "Wa takūnul-jibālu kal-‘ihnil-manfūsy(i).", "dan gunung-gunung seperti bulu yang berhamburan."),
    Ayah(6, 101, "فَاَمَّا مَنْ ثَقُلَتْ مَوَازِينُهٗۙ", "Fa ammā man ṡaqulat mawāzīnuh(ū).", "Siapa yang berat timbangan (kebaikan)-nya,"),
    Ayah(7, 101, "فَهُوَ فِيْ عِيْشَةٍ رَّاضِيَةٍۗ", "Fa huwa fī ‘īsyatir rāḍiyah(tin).", "dia berada dalam kehidupan yang menyenangkan."),
    Ayah(8, 101, "وَاَمَّا مَنْ خَفَّتْ مَوَازِيْنُهٗۙ", "Wa ammā man khaffat mawāzīnuh(ū).", "Adapun orang yang ringan timbangan (kebaikan)-nya,"),
    Ayah(9, 101, "فَاُمُّهٗ هَاوِيَةٌ ۗ", "Fa ummuhū hāwiyah(tun).", "tempat kembalinya adalah (neraka) Hawiyah."),
    Ayah(10, 101, "وَمَآ اَدْرٰىكَ مَا هِيَهْۗ", "Wa mā adrāka mā hiyah.", "Tahukah kamu apakah (neraka Hawiyah) itu?"),
    Ayah(11, 101, "نَارٌ حَامِيَةٌ ࣖ", "Nārun ḥāmiyah(tun).", "(Ia adalah) api yang sangat panas."),
)

internal fun quranFullAyahs102(): List<Ayah> = listOf(
    Ayah(1, 102, "اَلْهٰىكُمُ التَّكَاثُرُۙ", "Alhākumut-takāṡur(u).", "Berbangga-bangga dalam memperbanyak (dunia) telah melalaikanmu"),
    Ayah(2, 102, "حَتّٰى زُرْتُمُ الْمَقَابِرَۗ", "Ḥattā zurtumul-maqābir(a).", "sampai kamu masuk ke dalam kubur."),
    Ayah(3, 102, "كَلَّا سَوْفَ تَعْلَمُوْنَۙ", "Kallā saufa ta‘lamūn(a).", "Sekali-kali tidak! Kelak kamu akan mengetahui (akibat perbuatanmu itu)."),
    Ayah(4, 102, "ثُمَّ كَلَّا سَوْفَ تَعْلَمُوْنَ", "Ṡumma kallā saufa ta‘lamūn(a).", "Sekali-kali tidak (jangan melakukan itu)! Kelak kamu akan mengetahui (akibatnya)."),
    Ayah(5, 102, "كَلَّا لَوْ تَعْلَمُوْنَ عِلْمَ الْيَقِيْنِۗ", "Kallā lau ta‘lamūna ‘ilmal-yaqīn(i).", "Sekali-kali tidak (jangan melakukan itu)! Sekiranya kamu mengetahui dengan pasti, (niscaya kamu tidak akan melakukannya)."),
    Ayah(6, 102, "لَتَرَوُنَّ الْجَحِيْمَۙ", "Latarawunnal-jaḥīm(a).", "Pasti kamu benar-benar akan melihat (neraka) Jahim."),
    Ayah(7, 102, "ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِيْنِۙ", "Ṡumma latarawunnahā ‘ainal-yaqīn(i).", "Kemudian, kamu pasti benar-benar akan melihatnya dengan ainulyakin."),
    Ayah(8, 102, "ثُمَّ لَتُسْـَٔلُنَّ يَوْمَىِٕذٍ عَنِ النَّعِيْمِ ࣖ", "Ṡumma latus'alunna yauma'iżin ‘anin-na‘īm(i).", "Kemudian, kamu pasti benar-benar akan ditanya pada hari itu tentang kenikmatan (yang megah di dunia itu)."),
)

internal fun quranFullAyahs103(): List<Ayah> = listOf(
    Ayah(1, 103, "وَالْعَصْرِۙ", "Wal-‘aṣr(i).", "Demi masa,"),
    Ayah(2, 103, "اِنَّ الْاِنْسَانَ لَفِيْ خُسْرٍۙ", "Innal-insāna lafī khusr(in).", "sesungguhnya manusia benar-benar berada dalam kerugian,"),
    Ayah(3, 103, "اِلَّا الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ وَتَوَاصَوْا بِالْحَقِّ ەۙ وَتَوَاصَوْا بِالصَّبْرِ ࣖ", "Illal-lażīna āmanū wa ‘amiluṣ-ṣāliḥāti wa tawāṣau bil-ḥaqq(i), wa tawāṣau biṣ-ṣabr(i).", "kecuali orang-orang yang beriman dan beramal saleh serta saling menasihati untuk kebenaran dan kesabaran."),
)

internal fun quranFullAyahs104(): List<Ayah> = listOf(
    Ayah(1, 104, "وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍۙ", "Wailul likulli humazatil-lumazah(tin).", "Celakalah setiap pengumpat lagi pencela"),
    Ayah(2, 104, "ۨالَّذِيْ جَمَعَ مَالًا وَّعَدَّدَهٗۙ", "Allażī jama‘a mālaw wa ‘addadah(ū).", "yang mengumpulkan harta dan menghitung-hitungnya."),
    Ayah(3, 104, "يَحْسَبُ اَنَّ مَالَهٗٓ اَخْلَدَهٗۚ", "Yaḥsabu anna mālahū akhladah(ū).", "Dia (manusia) mengira bahwa hartanya dapat mengekalkannya."),
    Ayah(4, 104, "كَلَّا لَيُنْۢبَذَنَّ فِى الْحُطَمَةِۖ", "Kallā layumbażanna fil-ḥuṭamah(ti).", "Sekali-kali tidak! Pasti dia akan dilemparkan ke dalam (neraka) Hutamah."),
    Ayah(5, 104, "وَمَآ اَدْرٰىكَ مَا الْحُطَمَةُ ۗ", "Wa mā adrāka mal-ḥuṭamah(tu).", "Tahukah kamu apakah (neraka) Hutamah?"),
    Ayah(6, 104, "نَارُ اللّٰهِ الْمُوْقَدَةُۙ", "Nārullāhil-mūqadah(tu).", "(Ia adalah) api (azab) اللّه yang dinyalakan"),
    Ayah(7, 104, "الَّتِيْ تَطَّلِعُ عَلَى الْاَفْـِٕدَةِۗ", "Allatī taṭṭali‘u ‘alal-af'idah(ti).", "yang (membakar) naik sampai ke hati."),
    Ayah(8, 104, "اِنَّهَا عَلَيْهِمْ مُّؤْصَدَةٌۙ", "Innahā ‘alaihim mu'ṣadah(tun).", "Sesungguhnya dia (api itu) tertutup rapat (sebagai hukuman) atas mereka,"),
    Ayah(9, 104, "فِيْ عَمَدٍ مُّمَدَّدَةٍ ࣖ", "Fī ‘amadim mumaddadah(tin).", "(sedangkan mereka) diikat pada tiang-tiang yang panjang."),
)

internal fun quranFullAyahs105(): List<Ayah> = listOf(
    Ayah(1, 105, "اَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِاَصْحٰبِ الْفِيْلِۗ", "Alam tara kaifa fa‘ala rabbuka bi'aṣḥābil-fīl(i).", "Tidakkah engkau (Nabi Muhammad) memperhatikan bagaimana Tuhanmu telah bertindak terhadap pasukan bergajah?"),
    Ayah(2, 105, "اَلَمْ يَجْعَلْ كَيْدَهُمْ فِيْ تَضْلِيْلٍۙ", "Alam yaj‘al kaidahum fī taḍlīl(in).", "Bukankah Dia telah menjadikan tipu daya mereka itu sia-sia?"),
    Ayah(3, 105, "وَّاَرْسَلَ عَلَيْهِمْ طَيْرًا اَبَابِيْلَۙ", "Wa arsala ‘alaihim ṭairan abābīl(a).", "Dia mengirimkan kepada mereka burung yang berbondong-bondong"),
    Ayah(4, 105, "تَرْمِيْهِمْ بِحِجَارَةٍ مِّنْ سِجِّيْلٍۙ", "Tarmīhim biḥijāratim min sijjīl(in).", "yang melempari mereka dengan batu dari tanah liat yang dibakar,"),
    Ayah(5, 105, "فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُوْلٍ ࣖ", "Fa ja‘alahum ka‘aṣfim ma'kūl(in).", "sehingga Dia menjadikan mereka seperti daun-daun yang dimakan (ulat)."),
)

internal fun quranFullAyahs106(): List<Ayah> = listOf(
    Ayah(1, 106, "لِاِيْلٰفِ قُرَيْشٍۙ", "Li'īlāfi quraisy(in).", "Disebabkan oleh kebiasaan orang-orang Quraisy,"),
    Ayah(2, 106, "اٖلٰفِهِمْ رِحْلَةَ الشِّتَاۤءِ وَالصَّيْفِۚ", "´lāfihim riḥlatasy-syitā'i waṣ-ṣaif(i).", "(yaitu) kebiasaan mereka bepergian pada musim dingin dan musim panas (sehingga mendapatkan banyak keuntungan),"),
    Ayah(3, 106, "فَلْيَعْبُدُوْا رَبَّ هٰذَا الْبَيْتِۙ", "Falya‘budū rabba hāżal-bait(i).", "maka hendaklah mereka menyembah Tuhan (pemilik) rumah ini (Ka‘bah)"),
    Ayah(4, 106, "الَّذِيْٓ اَطْعَمَهُمْ مِّنْ جُوْعٍ ەۙ وَّاٰمَنَهُمْ مِّنْ خَوْفٍ ࣖ", "Allażī aṭ‘amahum min jū‘(in), wa āmanahum min khauf(in).", "yang telah memberi mereka makanan untuk menghilangkan lapar dan mengamankan mereka dari rasa takut."),
)

internal fun quranFullAyahs107(): List<Ayah> = listOf(
    Ayah(1, 107, "اَرَءَيْتَ الَّذِيْ يُكَذِّبُ بِالدِّيْنِۗ", "Ara'aital-lażī yukażżibu bid-dīn(i).", "Tahukah kamu (orang) yang mendustakan agama?"),
    Ayah(2, 107, "فَذٰلِكَ الَّذِيْ يَدُعُّ الْيَتِيْمَۙ", "Fa żālikal-lażī yadu‘‘ul-yatīm(a).", "Itulah orang yang menghardik anak yatim"),
    Ayah(3, 107, "وَلَا يَحُضُّ عَلٰى طَعَامِ الْمِسْكِيْنِۗ", "Wa lā yaḥuḍḍu ‘alā ṭa‘āmil-miskīn(i).", "dan tidak menganjurkan untuk memberi makan orang miskin."),
    Ayah(4, 107, "فَوَيْلٌ لِّلْمُصَلِّيْنَۙ", "Fawailul lil-muṣallīn(a).", "Celakalah orang-orang yang melaksanakan salat,"),
    Ayah(5, 107, "الَّذِيْنَ هُمْ عَنْ صَلَاتِهِمْ سَاهُوْنَۙ", "Allażīna hum ‘an ṣalātihim sāhūn(a).", "(yaitu) yang lalai terhadap salatnya,"),
    Ayah(6, 107, "الَّذِيْنَ هُمْ يُرَاۤءُوْنَۙ", "Allażīna hum yurā'ūn(a).", "yang berbuat riya,"),
    Ayah(7, 107, "وَيَمْنَعُوْنَ الْمَاعُوْنَ ࣖ", "Wa yamna‘ūnal-mā‘ūn(a).", "dan enggan (memberi) bantuan."),
)

internal fun quranFullAyahs108(): List<Ayah> = listOf(
    Ayah(1, 108, "اِنَّآ اَعْطَيْنٰكَ الْكَوْثَرَۗ", "Innā a‘ṭainākal-kauṡar(a).", "Sesungguhnya Kami telah memberimu (Nabi Muhammad) nikmat yang banyak."),
    Ayah(2, 108, "فَصَلِّ لِرَبِّكَ وَانْحَرْۗ", "Faṣalli lirabbika wanḥar.", "Maka, laksanakanlah salat karena Tuhanmu dan berkurbanlah!"),
    Ayah(3, 108, "اِنَّ شَانِئَكَ هُوَ الْاَبْتَرُ ࣖ", "Inna syāni'aka huwal-abtar(u).", "Sesungguhnya orang yang membencimu, dialah yang terputus (dari rahmat اللّه)."),
)

internal fun quranFullAyahs109(): List<Ayah> = listOf(
    Ayah(1, 109, "قُلْ يٰٓاَيُّهَا الْكٰفِرُوْنَۙ", "Qul yā ayyuhal-kāfirūn(a).", "Katakanlah (Nabi Muhammad), “Wahai orang-orang kafir,"),
    Ayah(2, 109, "لَآ اَعْبُدُ مَا تَعْبُدُوْنَۙ", "Lā a‘budu mā ta‘budūn(a).", "aku tidak akan menyembah apa yang kamu sembah."),
    Ayah(3, 109, "وَلَآ اَنْتُمْ عٰبِدُوْنَ مَآ اَعْبُدُۚ", "Wa lā antum ‘ābidūna mā a‘bud(u).", "Kamu juga bukan penyembah apa yang aku sembah."),
    Ayah(4, 109, "وَلَآ اَنَا۠ عَابِدٌ مَّا عَبَدْتُّمْۙ", "Wa lā ana ‘ābidum mā ‘abattum.", "Aku juga tidak pernah menjadi penyembah apa yang kamu sembah."),
    Ayah(5, 109, "وَلَآ اَنْتُمْ عٰبِدُوْنَ مَآ اَعْبُدُۗ", "Wa lā antum ‘ābidūna mā a‘bud(u).", "Kamu tidak pernah (pula) menjadi penyembah apa yang aku sembah."),
    Ayah(6, 109, "لَكُمْ دِيْنُكُمْ وَلِيَ دِيْنِ ࣖ", "Lakum dīnukum wa liya dīn(i).", "Untukmu agamamu dan untukku agamaku.”"),
)

internal fun quranFullAyahs110(): List<Ayah> = listOf(
    Ayah(1, 110, "اِذَا جَاۤءَ نَصْرُ اللّٰهِ وَالْفَتْحُۙ", "Iżā jā'a naṣrullāhi wal-fatḥ(u).", "Apabila telah datang pertolongan اللّه dan kemenangan"),
    Ayah(2, 110, "وَرَاَيْتَ النَّاسَ يَدْخُلُوْنَ فِيْ دِيْنِ اللّٰهِ اَفْوَاجًاۙ", "Wa ra'aitan-nāsa yadkhulūna fī dīnillāhi afwājā(n).", "dan engkau melihat manusia berbondong-bondong masuk agama اللّه,"),
    Ayah(3, 110, "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُۗ اِنَّهٗ كَانَ تَوَّابًا ࣖ", "Fasabbiḥ biḥamdi rabbika wastagfirh(u), innahū kāna tawwābā(n).", "bertasbihlah dengan memuji Tuhanmu dan mohonlah ampun kepada-Nya. Sesungguhnya Dia Maha Penerima tobat."),
)

internal fun quranFullAyahs111(): List<Ayah> = listOf(
    Ayah(1, 111, "تَبَّتْ يَدَآ اَبِيْ لَهَبٍ وَّتَبَّۗ", "Tabbat yadā abī lahabiw wa tabb(a).", "Binasalah kedua tangan Abu Lahab dan benar-benar binasa dia."),
    Ayah(2, 111, "مَآ اَغْنٰى عَنْهُ مَالُهٗ وَمَا كَسَبَۗ", "Mā agnā ‘anhu māluhū wa mā kasab(a).", "Tidaklah berguna baginya hartanya dan apa yang dia usahakan."),
    Ayah(3, 111, "سَيَصْلٰى نَارًا ذَاتَ لَهَبٍۙ", "Sayaṣlā nāran żāta lahab(in).", "Kelak dia akan memasuki api yang bergejolak (neraka),"),
    Ayah(4, 111, "وَّامْرَاَتُهٗ ۗحَمَّالَةَ الْحَطَبِۚ", "Wamra'atuh(ū), ḥammālatal-ḥaṭab(i).", "(begitu pula) istrinya, pembawa kayu bakar (penyebar fitnah)."),
    Ayah(5, 111, "فِيْ جِيْدِهَا حَبْلٌ مِّنْ مَّسَدٍ ࣖ", "Fī jīdihā ḥablum mim masad(in).", "Di lehernya ada tali dari sabut yang dipintal."),
)

internal fun quranFullAyahs112(): List<Ayah> = listOf(
    Ayah(1, 112, "قُلْ هُوَ اللّٰهُ اَحَدٌۚ", "Qul huwallāhu aḥad(un).", "Katakanlah (Nabi Muhammad), “Dialah اللّه Yang Maha Esa."),
    Ayah(2, 112, "اَللّٰهُ الصَّمَدُۚ", "Allāhuṣ-ṣamad(u).", "اللّه tempat meminta segala sesuatu."),
    Ayah(3, 112, "لَمْ يَلِدْ وَلَمْ يُوْلَدْۙ", "Lam yalid wa lam yūlad.", "Dia tidak beranak dan tidak pula diperanakkan"),
    Ayah(4, 112, "وَلَمْ يَكُنْ لَّهٗ كُفُوًا اَحَدٌ ࣖ", "Wa lam yakul lahū kufuwan aḥad(un).", "serta tidak ada sesuatu pun yang setara dengan-Nya.”"),
)

internal fun quranFullAyahs113(): List<Ayah> = listOf(
    Ayah(1, 113, "قُلْ اَعُوْذُ بِرَبِّ الْفَلَقِۙ", "Qul a‘ūżu birabbil-falaq(i).", "Katakanlah (Nabi Muhammad), “Aku berlindung kepada Tuhan yang (menjaga) fajar (subuh)"),
    Ayah(2, 113, "مِنْ شَرِّ مَا خَلَقَۙ", "Min syarri mā khalaq(a).", "dari kejahatan (makhluk yang) Dia ciptakan,"),
    Ayah(3, 113, "وَمِنْ شَرِّ غَاسِقٍ اِذَا وَقَبَۙ", "Wa min syarri gāsiqin iżā waqab(a).", "dari kejahatan malam apabila telah gelap gulita,"),
    Ayah(4, 113, "وَمِنْ شَرِّ النَّفّٰثٰتِ فِى الْعُقَدِۙ", "Wa min syarrin-naffāṡāti fil-‘uqad(i).", "dari kejahatan perempuan-perempuan (penyihir) yang meniup pada buhul-buhul (talinya),"),
    Ayah(5, 113, "وَمِنْ شَرِّ حَاسِدٍ اِذَا حَسَدَ ࣖ", "Wa min syarri ḥāsidin iżā ḥasad(a).", "dan dari kejahatan orang yang dengki apabila dia dengki.”"),
)

internal fun quranFullAyahs114(): List<Ayah> = listOf(
    Ayah(1, 114, "قُلْ اَعُوْذُ بِرَبِّ النَّاسِۙ", "Qul a‘ūżu birabbin-nās(i).", "Katakanlah (Nabi Muhammad), “Aku berlindung kepada Tuhan manusia,"),
    Ayah(2, 114, "مَلِكِ النَّاسِۙ", "Malikin-nās(i).", "raja manusia,"),
    Ayah(3, 114, "اِلٰهِ النَّاسِۙ", "Ilāhin-nās(i).", "sembahan manusia"),
    Ayah(4, 114, "مِنْ شَرِّ الْوَسْوَاسِ ەۙ الْخَنَّاسِۖ", "Min syarril-waswāsil-khannās(i).", "dari kejahatan (setan) pembisik yang bersembunyi"),
    Ayah(5, 114, "الَّذِيْ يُوَسْوِسُ فِيْ صُدُوْرِ النَّاسِۙ", "Allażī yuwaswisu fī ṣudūrin-nās(i).", "yang membisikkan (kejahatan) ke dalam dada manusia,"),
    Ayah(6, 114, "مِنَ الْجِنَّةِ وَالنَّاسِ ࣖ", "Minal jinnati wan-nās(i).", "dari (golongan) jin dan manusia.”"),
)

